8}], \"content\": \"The 48-month revenue estimates for the highway and mass transit accounts, respectively, include the latest estimates received from Treasury's Office of Tax Analysis for excise taxes, net of refunds. They represent net highway receipts for those periods beginning at the close of fiscal year 2013.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [690, 512, 945, 552], \"page_id\": 108}], \"content\": \"Highway Account\", \"description\": null, \"id\": 5, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [687, 563, 949, 592], \"page_id\": 108}], \"content\": \"[In billions of dollars. Source: DOT]\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [155, 601, 1490, 926], \"page_id\": 108}], \"content\": \"Commitments (unobligated balances plus unpaid obligations, fiscal year 2013) 101\\nless:\\nCash balance (fiscal year 2013) 7\\nUnfunded authorizations (fiscal year 2013) 94\\n48-month revenue estimate (fiscal years 2014, 2015, 2016, and 2017) 142\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [661, 1110, 974, 1146], \"page_id\": 108}], \"content\": \"Mass Transit Account\", \"description\": null, \"id\": 8, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [685, 1155, 949, 1183], \"page_id\": 108}], \"content\": \"(In billions of dollars. Source: DOT)\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [151, 1195, 1486, 1518], \"page_id\": 108}], \"content\": \"Commitments (unobligated balances plus unpaid obligations, fiscal year 2013) 20\\nless:\\nCash balance (fiscal year 2013) 5\\nUnfunded authorizations (fiscal year 2013) 15\\n48-month revenue estimate (fiscal years 2014, 2015, 2016, and 2017) 20\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 1560, 441, 1586], \"page_id\": 108}], \"content\": \"* Numbers may not add due to rounding.\", \"description\": null, \"id\": 1