n\": null, \"id\": 7, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [144, 99, 173, 123], \"page_id\": 62}], \"content\": \"56\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [665, 99, 962, 125], \"page_id\": 62}], \"content\": \"CAPITAL MOVEMENTS\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [333, 200, 1300, 245], \"page_id\": 62}], \"content\": \"CHART CM-A.\\u2014U.S. Liabilities to Foreigners\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [162, 252, 1466, 290], \"page_id\": 62}], \"content\": \"Reported by U.S. Banks, Brokers, and Dealers with Respect to Selected Countries\", \"description\": null, \"id\": 3, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [246, 330, 1339, 915], \"page_id\": 62}], \"content\": null, \"description\": null, \"id\": 4, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [284, 997, 1346, 1518], \"page_id\": 62}], \"content\": null, \"description\": null, \"id\": 5, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [217, 1568, 1362, 1683], \"page_id\": 62}], \"content\": \"U.S. liabilities to foreigners reported by U.S. banks were recorded at $4.7 trillion in March 2013, an increase of $190 billion from yearend 2012. U.S. banking liabilities include foreign holdings of U.S. short-term securities but exclude foreign holdings of U.S. long-term securities. U.S. banking liabilities increased about $131 billion in 2010 and $304 billion in 2011. However, they decreased $393 billion in 2012.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [215, 1688, 1413, 1928], \"page_id\": 62}], \"content\": \"U.S. banking liabilities are concentrated in international financial centers. The data on this page show that about 55 percent of U.S. banking liabilities is currently recorded against the United Kingdom and banking centers in the Caribbean. Overall, banking liabilities rebounded in 2010 and 2011 from earlier declines, with the exception of Caribbean banking centers. In 2012, liabilities to Caribbean banking centers continued to fall and liabilities to other international financial centers and Japan turned down. However, liabilities to \\u201call other countries\\u201d have continued to grow at a steady pace in the post crisis years. In the first quarter of 2013, liabilities to most regions increased, especially those to the Caribbean banking centers, the United Kingdom, and \\u201call other Asia\\u201d.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 1989, 248, 2015], \"page_id\": 62}], \"content\": \"June 2013\", \"description\": null, \"id\": 8, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [661, 85, 978, 132], \"page_id\": 63}], \"content\": \"CAPITAL MOVEMENTS\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1441, 82, 1497, 139], \"page_id\": 63}], \"content\": \"57\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [189, 191, 1441, 240], \"page_id\": 63}], \"content\": \"SECTION II.\\u2014Claims on Foreigners Reported by Banks in the United States\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [526, 248, 1109, 297], \"page_id\": 63}], \"content\": \"TABLE CM-II-1.\\u2014Total Claims by Type\", \"description\": null, \"id\": 3, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [435, 295, 1191, 330], \"page_id\": 63}], \"content\": \"[Position at end of period in millions of dollars. Source: Treasury International Capital Reporting System]\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [133, 335, 1490, 1815], \"page_id\": 63}], \"content\": \"<table><tr><th>Type of Claim</th><th>Calendar Year 2010 r</th><th>2011 Dec. r</th><th>Mar. r</th><th>June r</th><th>Sept.</th><th>2012 Dec. p</th></tr><tr><td>Total claims</td><td>4,530,244</td><td>4,263,195</td><t