], \"page_id\": 114}], \"content\": \"June 2013\", \"description\": null, \"id\": 6, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [723, 99, 916, 127], \"page_id\": 115}], \"content\": \"TRUST FUNDS\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1443, 97, 1488, 127], \"page_id\": 115}], \"content\": \"111\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [368, 212, 1264, 255], \"page_id\": 115}], \"content\": \"INTRODUCTION: Hazardous Substance Superfund\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [142, 269, 800, 570], \"page_id\": 115}], \"content\": \"The Hazardous Substance Response Trust Fund was established on the books of the Treasury in fiscal year 1981, in accordance with section 221 of the Hazardous Substance Response Revenue Act of 1980 [42 United States Code 9631(a), repealed]. The trust fund was renamed the Hazardous Substance Superfund (Superfund) and relocated in accordance with section 517 of the Superfund Amendments and Reauthorization Act of 1986 [Public Law 99-499, dated October 17, 1986 (26 United States Code 9507)].\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 578, 800, 639], \"page_id\": 115}], \"content\": \"The authority to collect excise taxes on petroleum and chemicals, and an environmental tax for all corporations\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 269, 1495, 422], \"page_id\": 115}], \"content\": \"with modified alternative taxable income in excess of $2 million, expired in 1995. To implement the Superfund program, amounts are appropriated from the Superfund to the Environmental Protection Agency (EPA) for programmatic and administrative expenses.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [829, 431, 1488, 613], \"page_id\": 115}], \"content\": \"An annual report to Congress by the Secretary of Treasury is required by 26 United States Code 9602(a). These reports present the financial condition of the Superfund and the results of operation for the past fiscal year, and its expected condition during the next 5 fiscal years.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [461, 688, 1175, 764], \"page_id\": 115}], \"content\": \"TABLE TF-5.\\u2014Hazardous Substance Superfund 1,2 Results of Operations, Fiscal Year 2012\", \"description\": null, \"id\": 7, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [767, 773, 872, 797], \"page_id\": 115}], \"content\": \"[Source: EPA]\", \"description\": null, \"id\": 8, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [144, 797, 1490, 1768], \"page_id\": 115}], \"content\": \"<table><tr><td>Balance Oct. 1, 2011</td><td>$138,600,000</td></tr><tr><td>Receipts:</td><td></td></tr><tr><td>Crude and petroleum</td><td>-</td></tr><tr><td>Certain chemicals</td><td>-</td></tr><tr><td>Corporate environmental</td><td>-</td></tr><tr><td>General fund appropriation</td><td>1,075,000,000</td></tr><tr><td>Cost recoveries</td><td>45,000,000</td></tr><tr><td>Fines and penalties</td><td>1,000,000</td></tr><tr><td>Interest on investments</td><td>40,000,000</td></tr><tr><td>Offsetting collections</td><td>-</td></tr><tr><td>Agency for Toxic Substance and Disease Registry offsetting collections</td><td>-</td></tr><tr><td>Total receipts</td><td>1,161,000,000</td></tr><tr><td>Expenses:</td><td></td></tr><tr><td>EPA expense</td><td>1,214,000,000</td></tr><tr><td>Other expenses</td><td>6,000,000</td></tr><tr><td>Total expenses</td><td>1,220,000,000</td></tr><tr><td>Balance Sept. 30, 2012</td><td>$79,600,000</td></tr></table>\", \"description\": null, \"id\": 9, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [158, 1813, 794, 1890], \"page_id\": 115}], \"content\": \"1 Reporting in this Superfund Trust Fund table is consistent with previously reported presentations. However, the structure of this table may not accurately reflect the status of this trust fund. As a result, this table may be revised in future reports and other resources should be utilized for accurate trust fund reporting.\", \"description\": null, \"id\": 10, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [827, 1810, 1457, 1853], \"page_id\": 115}], \"content\": \"2 Reporting excludes the Iron Mountain account in the Hazardous Substance Superfund Trust Fund.\", \"description\": null, \"id\": 11, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [1388, 1987, 1492, 2018], \"page_id\": 115}], \"content\": \"June 2013\", \"description\": null, \"id\": 12, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [142, 99, 189, 123], \"page_id\": 116}], \"content\": \"112\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [719, 101, 916, 125], \"page_id\": 116}], \"content\": \"TRUST FUNDS\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [322, 200, 1317, 264], \"page_id\": 116}], \"content\": \"Hazardous Substance Superfund Expected Condition and Results of Operations, Fiscal Years 2013-2017 1\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [690, 278, 944, 302], \"page_id\": 116}], \"content\": \"(In millions of dollars. Source: EPA)\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 297, 1495, 1202], \"page_id\": 116}], \"content\": \"<table><tr><th></th><th>2013</th><th>2014</th><th>2015</th><th>2016</th><th>2017</th></tr><tr><td>Balance Oct. 1</td><td>80</td><td>136</td><td>1,714</td><td>2,781</td><td>3,948</td></tr><tr><td>Receipts:</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Interest</td><td>48</td><td>64</td><td>80</td><td>99</td><td>115</td></tr><tr><td>Recoveries</td><td>100</td><td>98</td><td>98</td><td>98</td><td>98</td></tr><tr><td>Fines and penalties</td><td>2</td><td>2</td><td>2</td><td>2</td><td>2</td></tr><tr><td>Taxes<sup>2