\"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [137, 243, 801, 434], \"page_id\": 108}], \"content\": \"The following information is released according to the provisions of the Byrd Amendment [codified at 26 United States Code 9503(d)] and represents data concerning the Highway Trust Fund. The figure described as \\\"unfunded authorizations\\\" is the latest estimate received from the DOT for fiscal year 2011.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [829, 243, 1495, 434], \"page_id\": 108}], \"content\": \"The 48-month revenue estimates for the highway and mass transit accounts, respectively, include the latest estimates received from Treasury's Office of Tax Analysis for excise taxes, net of refunds. They represent net highway receipts for those periods beginning at the close of fiscal year 2011.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [681, 514, 956, 552], \"page_id\": 108}], \"content\": \"Highway Account *\", \"description\": null, \"id\": 5, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [692, 559, 951, 589], \"page_id\": 108}], \"content\": \"(In billions of dollars. Source: DOT)\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [151, 596, 1494, 945], \"page_id\": 108}], \"content\": \"<table><tr><td>Commitments (unobligated balances plus unpaid obligations, fiscal year 2012)</td><td>105</td></tr><tr><td>less:</td><td></td></tr><tr><td>Cash balance (fiscal year 2012)</td><td>8</td></tr><tr><td>Unfunded authorizations (fiscal year 2012)</td><td>97</td></tr><tr><td>48-month revenue estimate (fiscal years 2013, 2014, 2015, and 2016)</td><td>143</td></tr></table>\", \"description\": null, \"id\": 7, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [153, 959, 723, 985], \"page_id\": 108}], \"content\": \"* Assumes the current stream of revenues and spending levels are maintained.\", \"description\": null, \"id\": 8, \"type\": \"footnote\"