ox\": [{\"coord\": [1439, 92, 1492, 127], \"page_id\": 113}], \"content\": \"109\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [381, 207, 1255, 255], \"page_id\": 113}], \"content\": \"INTRODUCTION: Harbor Maintenance Trust Fund\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [142, 264, 798, 389], \"page_id\": 113}], \"content\": \"The Harbor Maintenance Trust Fund was established on the books of the Treasury on April 1, 1987, according to the Water Resources Development Act of 1986 (Public Law 99-662, November 17, 1986) (26 United States Code 9505).\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 391, 800, 943], \"page_id\": 113}], \"content\": \"Amounts in the Harbor Maintenance Trust Fund are available as provided by appropriation acts for making expenditures to carry out section 210(a) of the Water Resources Development Act of 1986. The appropriations act for the Department of Transportation (DOT) for fiscal year 1995 (Public Law 103-331, September 28, 1994), section 339, waived collection of charges or tolls on the Saint Lawrence Seaway in accordance with section 13(b) of the Act of May 13, 1954 (as in effect on April 1, 1987). Legislation was passed in the North American Free Trade Agreement Implementation Act (Public Law 103-182, section 683), which amends paragraph (3) of section 9505(c) of the IRC of 1986, to authorize payment of up to $5 million annually to Treasury for all expenses of administration incurred by the Treasury, the U.S. Army Corps of Engineers and the Department of Commerce (Commerce) related to the administration of subchapter A of chapter 36 (relating to harbor maintenance tax). Section 201 of the Water\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 269, 1488, 422], \"page_id\": 113}], \"content\": \"Resources Development Act of 1996 (Public Law 104-303) authorizes use of the Harbor Maintenance Trust Fund for construction of dredged material disposal facilities associated with the operation and maintenance of Federal navigation projects for commercial navigation.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 424, 1490, 606], \"page_id\": 113}], \"content\": \"A summary judgment issued October 25, 1995, by the United States Court of International Trade in the case United States Shoe Corp. v. United States (Court No. 94-11-00668) found the Harbor Maintenance fee unconstitutional under the Export Clause of the Constitution (Article I, section 9, clause 5) and enjoined the Customs Service from collecting the fee.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 608, 1494, 728], \"page_id\": 113}], \"content\": \"The decision was affirmed by the Supreme Court on March 31, 1998 (118 Supreme Court 1290). With the tax on exports no longer collected, revenues have been reduced by approximately 30 percent.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [829, 731, 1495, 912], \"page_id\": 113}], \"content\": \"The Code requires the Secretary of the Treasury to submit an annual report to Congress [26 United States Code 9602(a)]. The report must present the financial condition and results of operations of the fund during the past fiscal year and the expected condition and operations of the fund during the next 5 fiscal years.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [474, 997, 1157, 1072], \"page_id\": 113}], \"content\": \"TABLE TF-4.\\u2014Harbor Maintenance Trust Fund Results of Operations, Fiscal Year 2012\", \"description\": null, \"id\": 9, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [623, 1080, 1009, 1108], \"page_id\": 113}], \"content\": \"[Source: Department of the Army Corps of Engineers]\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 1122, 1475, 18